insert into public.content_items(id,version,kind,title,published) values('chapter-1-v22',1,'quiz','Data literacy',true);
insert into private.assessment_keys(content_id,content_version,solution) values('chapter-1-v22',1,$keys$[{"id": "c1q1", "kind": "single", "skill": "Data literacy", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "A row records a visit; hospitals may recur and columns are variables."}, {"id": "c1q2", "kind": "multi", "skill": "Data literacy", "answer": ["o0", "o1"], "options": ["o0", "o1", "o2", "o3"], "explanation": "Payment method and region name categories. Price and weight measure amounts."}, {"id": "c1q3", "kind": "boolean", "skill": "Data literacy", "answer": "o1", "options": ["o0", "o1"], "explanation": "Other variables can explain an association; an experiment or defensible causal design is needed."}, {"id": "c1q4", "kind": "numeric", "skill": "Data literacy", "answer": 32, "options": [], "explanation": "Multiply 8 observations by 4 fields: 32 cells."}, {"id": "c1q5", "kind": "scenario", "skill": "Data literacy", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Random assignment reduces confounding. Happy customers are selected; designer opinion is not outcome evidence."}, {"id": "c1q6", "kind": "single", "skill": "Data literacy", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Mean duration can be measured and compared; the alternatives are subjective or undefined."}]$keys$::jsonb);
insert into public.content_items(id,version,kind,title,published) values('chapter-2-v22',1,'quiz','Python foundations',true);
insert into private.assessment_keys(content_id,content_version,solution) values('chapter-2-v22',1,$keys$[{"id": "c2q1", "kind": "output", "skill": "Python foundations", "answer": "o1", "options": ["o0", "o1", "o2"], "explanation": "Python indexes from zero: index 1 selects the second value, 8."}, {"id": "c2q2", "kind": "numeric", "skill": "Python foundations", "answer": 5, "options": [], "explanation": "len counts five list elements, not their sum or last value."}, {"id": "c2q3", "kind": "output", "skill": "Python foundations", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Multiplication occurs before addition: 12 + 2 = 14."}, {"id": "c2q4", "kind": "boolean", "skill": "Python foundations", "answer": "o1", "options": ["o0", "o1"], "explanation": "A single equals sign assigns. Two equals signs compare."}, {"id": "c2q5", "kind": "multi", "skill": "Python foundations", "answer": ["o0", "o1"], "options": ["o0", "o1", "o2", "o3"], "explanation": "Three exceeds two and two equals two. The other comparisons are false."}, {"id": "c2q6", "kind": "scenario", "skill": "Python foundations", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "A loop must reach a stopping condition. Visual styles cannot change that logic."}]$keys$::jsonb);
insert into public.content_items(id,version,kind,title,published) values('chapter-3-v22',1,'quiz','Data cleaning',true);
insert into private.assessment_keys(content_id,content_version,solution) values('chapter-3-v22',1,$keys$[{"id": "c3q1", "kind": "numeric", "skill": "Data cleaning", "answer": 18, "options": [], "explanation": "The observed total is 36 across two observations: 18. Missing is not zero."}, {"id": "c3q2", "kind": "single", "skill": "Data cleaning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Each column is a variable measured across rows. A person may correspond to a row."}, {"id": "c3q3", "kind": "scenario", "skill": "Data cleaning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Repeated IDs can mean updates. Blind deletion or replacement can corrupt evidence."}, {"id": "c3q4", "kind": "boolean", "skill": "Data cleaning", "answer": "o1", "options": ["o0", "o1"], "explanation": "Zero is a real amount and changes the distribution; unknown is not measured zero."}, {"id": "c3q5", "kind": "numeric", "skill": "Data cleaning", "answer": 2, "options": [], "explanation": "15 and 20 satisfy the strict comparison; 10 does not."}, {"id": "c3q6", "kind": "multi", "skill": "Data cleaning", "answer": ["o0", "o1"], "options": ["o0", "o1", "o2", "o3"], "explanation": "Removal and imputation affect results and reproducibility; colors do not document those transformations."}]$keys$::jsonb);
insert into public.content_items(id,version,kind,title,published) values('chapter-4-v22',1,'quiz','Visual reasoning',true);
insert into private.assessment_keys(content_id,content_version,solution) values('chapter-4-v22',1,$keys$[{"id": "c4q1", "kind": "chart", "skill": "Visual reasoning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "The difference is 30 - 20 = 10. The ratio is 1.5, not 3."}, {"id": "c4q2", "kind": "numeric", "skill": "Visual reasoning", "answer": 15, "options": [], "explanation": "Non-overlapping histogram bin counts sum to 3 + 5 + 7 = 15."}, {"id": "c4q3", "kind": "single", "skill": "Visual reasoning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "A histogram groups numeric observations into bins. Labels and meaningful encodings are essential."}, {"id": "c4q4", "kind": "boolean", "skill": "Visual reasoning", "answer": "o0", "options": ["o0", "o1"], "explanation": "Bar length encodes magnitude; a truncated baseline can inflate the apparent ratio."}, {"id": "c4q5", "kind": "scenario", "skill": "Visual reasoning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Counts expose limited evidence; two records cannot guarantee representativeness."}, {"id": "c4q6", "kind": "multi", "skill": "Visual reasoning", "answer": ["o0", "o1"], "options": ["o0", "o1", "o2", "o3"], "explanation": "Units and group definitions explain encoding. Hidden exclusions and unlabeled scale changes obscure meaning."}]$keys$::jsonb);
insert into public.content_items(id,version,kind,title,published) values('chapter-5-v22',1,'quiz','Statistical reasoning',true);
insert into private.assessment_keys(content_id,content_version,solution) values('chapter-5-v22',1,$keys$[{"id": "c5q1", "kind": "numeric", "skill": "Statistical reasoning", "answer": 16, "options": [], "explanation": "The sum is 48; divide by 3 to get 16."}, {"id": "c5q2", "kind": "numeric", "skill": "Statistical reasoning", "answer": 9, "options": [], "explanation": "Average the middle pair: (7 + 11) / 2 = 9."}, {"id": "c5q3", "kind": "single", "skill": "Statistical reasoning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "The sum and mean rise. Count and minimum remain unchanged."}, {"id": "c5q4", "kind": "boolean", "skill": "Statistical reasoning", "answer": "o1", "options": ["o0", "o1"], "explanation": "More biased observations improve precision about the wrong source, not representativeness."}, {"id": "c5q5", "kind": "numeric", "skill": "Statistical reasoning", "answer": 12, "options": [], "explanation": "Range is maximum minus minimum: 16 - 4 = 12."}, {"id": "c5q6", "kind": "scenario", "skill": "Statistical reasoning", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Variation can arise from chance or selection. Preference is not evidence of accuracy."}]$keys$::jsonb);
insert into public.content_items(id,version,kind,title,published) values('chapter-6-v22',1,'quiz','Evaluation',true);
insert into private.assessment_keys(content_id,content_version,solution) values('chapter-6-v22',1,$keys$[{"id": "c6q1", "kind": "single", "skill": "Evaluation", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Final duration is the target observed after delivery; it is unavailable for genuine advance prediction."}, {"id": "c6q2", "kind": "numeric", "skill": "Evaluation", "answer": 3, "options": [], "explanation": "Absolute errors are 2 and 4, so MAE is 3."}, {"id": "c6q3", "kind": "boolean", "skill": "Evaluation", "answer": "o1", "options": ["o0", "o1"], "explanation": "Tuning uses test information. Keep a fresh held-out evaluation or use a separate validation split."}, {"id": "c6q4", "kind": "scenario", "skill": "Evaluation", "answer": "o0", "options": ["o0", "o1", "o2"], "explanation": "Fit transformations on training data and apply them to held-out data without refitting."}, {"id": "c6q5", "kind": "multi", "skill": "Evaluation", "answer": ["o0", "o1"], "options": ["o0", "o1", "o2", "o3"], "explanation": "Metric meaning and held-out sample definition make evaluation interpretable; guarantees are unsupported."}, {"id": "c6q6", "kind": "numeric", "skill": "Evaluation", "answer": 3, "options": [], "explanation": "The error falls by 8 - 5 = 3 units. This is an absolute reduction, not a percentage."}]$keys$::jsonb);
create function public.grade_chapter_quiz(p_content_id text,p_request_id uuid,p_answers jsonb,p_owner uuid) returns public.quiz_attempts language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); saved public.quiz_attempts; keys jsonb; q jsonb; response jsonb; normalized jsonb; correct boolean; score integer:=0; feedback jsonb:='[]';
begin
 if uid is null or uid is distinct from p_owner then raise exception 'Authentication required' using errcode='42501';end if;
 if p_content_id not in ('chapter-1-v22','chapter-2-v22','chapter-3-v22','chapter-4-v22','chapter-5-v22','chapter-6-v22') then raise exception 'Unknown assessment' using errcode='22023'; end if;
 if p_request_id is null or p_answers is null or jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>12000 then raise exception 'Invalid answers' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(uid::text||':quiz',0));
 select * into saved from public.quiz_attempts where user_id=uid and request_id=p_request_id;
 if found then
  if saved.responses<>p_answers or saved.content_id<>p_content_id then raise exception 'Request already used with different answers' using errcode='22023';end if;
  return saved;
 end if;
 if (select count(*) from public.quiz_attempts where user_id=uid and created_at>now()-interval '1 hour')>=20 then raise exception 'Hourly attempt limit reached' using errcode='54000';end if;
 select solution into keys from private.assessment_keys where assessment_keys.content_id=p_content_id and content_version=1;
 if (select count(*) from jsonb_object_keys(p_answers))<>jsonb_array_length(keys) then raise exception 'Answer all questions exactly once' using errcode='22023';end if;
 for q in select value from jsonb_array_elements(keys) loop
  response:=p_answers->(q->>'id');correct:=false;
  if response is null then raise exception 'Missing answer' using errcode='22023';end if;
  if q->>'kind'='numeric' then
   if jsonb_typeof(response)<>'number' then raise exception 'Numeric answer required' using errcode='22023';end if;
   correct:=abs((response#>>'{}')::numeric-(q->>'answer')::numeric)<=0.001;
  elsif q->>'kind'='multi' then
   if jsonb_typeof(response)<>'array' or jsonb_array_length(response)>4 or jsonb_array_length(response)=0 then raise exception 'Invalid selections' using errcode='22023';end if;
   if exists(select 1 from jsonb_array_elements(response) v where not(q->'options' @> jsonb_build_array(v))) then raise exception 'Unknown option' using errcode='22023';end if;
   select jsonb_agg(value order by value) into normalized from (select distinct value from jsonb_array_elements(response)) s;
   if jsonb_array_length(normalized)<>jsonb_array_length(response) then raise exception 'Duplicate option' using errcode='22023';end if;
   correct:=normalized=q->'answer';
  else
   if jsonb_typeof(response)<>'string' or not(q->'options' @> jsonb_build_array(response)) then raise exception 'Unknown option' using errcode='22023';end if;
   correct:=response=q->'answer';
  end if;
  if correct then score:=score+1;end if;
  feedback:=feedback||jsonb_build_array(jsonb_build_object('id',q->>'id','skill',q->>'skill','correct',correct,'explanation',q->>'explanation'));
 end loop;
 insert into public.quiz_attempts(user_id,content_id,content_version,request_id,responses,verified_score,feedback) values(uid,p_content_id,1,p_request_id,p_answers,score::numeric/jsonb_array_length(keys),feedback) returning * into saved;
 return saved;
end $$;
revoke all on function public.grade_chapter_quiz(text,uuid,jsonb,uuid) from public,anon;
grant execute on function public.grade_chapter_quiz(text,uuid,jsonb,uuid) to authenticated;
